let maxint (t:inttype) =
  if unsigned t then pow2 (bits t) - 1
  else pow2 (bits t - 1) - 1

let op_At_Percent_Dot x t : range_t t =
  if unsigned t then x % modulus t
  else x @% modulus t

let cast (#t:inttype) (#t':inttype)
    (u1:int_t t{range (v u1) t'}) =
    mk_int #t' (v u1)

let cast_mod (#t:inttype) (#t':inttype)
    (u1:int_t t) = 
    mk_int #t' (v u1 @%. t')

let add (#t:inttype) (a:int_t t)
        (b:int_t t{range (v a + v b) t}) =
    mk_int #t (v a + v b)

let mul_mod (#t:inttype) (a:int_t t)
            (b:int_t t) =
            mk_int #t (v a * v b @%. t)

let mul_overflow (#t:inttype) (a:int_t t)
                 (b:int_t t) =
                 (mk_int #t (v a * v b @%. t), (v a * v b > maxint t || v a * v b < minint t))

let add_overflow (#t:inttype) (a:int_t t)
                 (b:int_t t) =
                 (mk_int #t ((v a + v b) @%. t), (v a + v b > maxint t || v a + v b < minint t))

let sub_overflow (#t:inttype) (a:int_t t)
                 (b:int_t t) =
                 (mk_int #t ((v a - v b) @%. t), (v a - v b > maxint t || v a - v b < minint t))

let mul (#t:inttype) (a:int_t t)
        (b:int_t t{range (v a * v b) t}) =
        mk_int #t (v a * v b)

let sub (#t:inttype) (a:int_t t)
        (b:int_t t{range (v a - v b) t}) =
    mk_int #t (v a - v b)

let trunc_div (a: int) (b: int{b <> 0}) : int =
  let q = abs a / abs b in
  if (a >= 0) = (b >= 0) then q else -q

let div (#t:inttype) (a:int_t t) (b:int_t t{v b <> 0 /\ (unsigned t \/ range (trunc_div (v a) (v b)) t)}) =
  if unsigned t
  then mk_int #t (v a / v b)
  else mk_int #t (trunc_div (v a) (v b))

let mod (#t:inttype) (a:int_t t) (b:int_t t{v b <> 0 /\ (unsigned t \/ range (trunc_div (v a) (v b)) t)}) =
  if unsigned t
  then mk_int #t (v a % v b)
  else mk_int #t (trunc_mod (v a) (v b))

let ones (#t:inttype) : n:int_t t =
  if unsigned t then mk_int #t (pow2 (bits t) - 1)
  else mk_int #t (-1)

