              let (i, s_chunk) = it in
                v i < Seq.length s / v chunk_len
              /\ nth_chunk_of s s_chunk (v i)
              /\ inv acc i
        }
      -> acc': acc_t {inv acc' (fst it +! sz 1)}
      )
  )
  : res:acc_t{inv res (length s /! chunk_len)}

